function clampCrop(W, H, x, y, w, h){
  if(x<0){ w+=x; x=0; } if(y<0){ h+=y; y=0; }
  if(x+w>W) w=W-x; if(y+h>H) h=H-y;
  var valid = (w>0 && h>0 && x<W && y<H);
  return { x:x, y:y, w:Math.max(0,w), h:Math.max(0,h), valid:valid };
}
function area(w, h){ return w*h; }
function aspect(w, h){ return h===0?NaN:w/h; }
var EXPORTS={ clampCrop:clampCrop, area:area, aspect:aspect };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CropForgePure = EXPORTS; }
